import{esc,button,input,range,select}from'../phase4/ui.js';
import * as v14 from './b14-view.js';
import{number,nodes,opText,expressionText,ready,innerTask,decimalPosition,divisionFinished,signRows,rootSteps}from'./b15-model.js';
const f=(k,l,v)=>input(k,l,v,'autocomplete="off" spellcheck="false"'),buttons=(a,xs,attr='value')=>xs.map(([v,l])=>button(a,l,`data-${attr}="${v}"`)).join('');
const ops=[['+','加'],['-','减'],['*','乘'],['/','除']],units={3:'千',2:'百',1:'十',0:'一','-1':'十分之一','-2':'百分之一','-3':'千分之一'};
const unit=n=>units[n]||`10的${n}次方`,prefix=s=>s.replaceAll('data-xfield="','data-xfield="inner.').replaceAll('data-xvalue="','data-xvalue="inner.');
function tree(n,b){if(n.op==='num')return `<span class="b15-num">${n.v}</span>`;if(Object.hasOwn(b.done,n.id))return `<span class="b15-done" title="${esc(expressionText(n))}">${b.done[n.id]}</span>`;return `<div class="b15-tree"><div class="b15-branches">${tree(n.a,b)}${n.b?tree(n.b,b):''}</div>${button('b15-op',n.op==='^'?'幂':opText(n.op),`data-index="${n.id}" aria-pressed="${b.selected===n.id}"`)}<small>${b.selected===n.id?'现在试这一步':''}</small></div>`;}
function order(t,m){const b=m.board;return `<p class="b15-expression">${esc(b.expression||t.expression||'把故事写成算式').replaceAll('*','×').replaceAll('/','÷')}</p>${b.tree?`<div class="b15-tree-scroll">${tree(b.tree,b)}</div>`:'<div class="b15-empty">括号可以把一组数抱在一起。</div>'}${t.writeOnly&&b.tree?'<p>上面的连接表示先后关系，这一步不用算出结果。</p>':''}${b.steps.length?`<ol class="b15-record">${b.steps.map(s=>`<li>${esc(s.expression)} = ${s.value}</li>`).join('')}</ol>`:''}`;}
function laws(t,m){const b=m.board,n=Math.max(1,Math.min(8,number(m.n)||1));return `<div class="b15-law"><section><b>${t.a}份，每份 n + ${t.b}</b>${Array.from({length:t.a},()=>`<div class="b15-strip"><span style="flex:${n}" class="variable">n = ${n}</span><span style="flex:${t.b}">${t.b}</span></div>`).join('')}</section><section><b>把每一份拆开，接到这里</b>${Array.from({length:b.n},()=>`<div class="b15-strip"><span class="variable" style="width:${n/(n+t.b)*100}%">n = ${n}</span></div>`).join('')}${Array.from({length:b.c},()=>`<div class="b15-strip"><span style="width:${t.b/(n+t.b)*100}%">${t.b}</span></div>`).join('')}</section></div>${b.trials.length?`<div class="b15-trials">${b.trials.map(x=>`<span>n=${x.n}：原来${x.left} ↔ 拼出${x.right}</span>`).join('')}</div>`:''}`;}
function shape(t,m){const skew=Math.max(0,Math.min(60,number(m.skew)||0));return `<svg class="b15-shape" viewBox="0 0 420 230" role="img" aria-label="两对对边平行的四边形，倾斜量${skew}"><polygon points="${50+skew},35 ${330+skew},35 330,190 50,190" fill="#eed8b1" stroke="#79562c" stroke-width="3"/><text x="${40+skew}" y="25">A${skew===0?' 90°':''}</text><text x="${330+skew}" y="25">B ?</text><text x="335" y="215">C ?</text><text x="35" y="215">D ?</text>${m.board.parallel.includes(0)?`<path d="M180 30l10 5-10 5 M180 185l10 5-10 5" fill="none" stroke="#356e68" stroke-width="3"/>`:''}${m.board.parallel.includes(1)?`<path d="M${50+skew/2-5} 110l5 10 5-10 M${330+skew/2-5} 110l5 10 5-10" fill="none" stroke="#356e68" stroke-width="3"/>`:''}</svg><div class="b15-actions">${[0,1].map((v)=>button('b15-parallel',v?'标出左右两边平行':'标出上下两边平行',`data-index="${v}" aria-pressed="${m.board.parallel.includes(v)}"`)).join('')}</div>`;}
function fraction(t,m){const p=Math.max(0,Math.min(1000,number(m.thousandths)||0));return `<div class="b15-fraction"><p>同样长的一整条，都表示1</p><div class="b15-eighths">${Array.from({length:8},(_,i)=>button('b15-fraction',m.board.selected.includes(i)?'●':'',`data-index="${i}" aria-label="第${i+1}份" aria-pressed="${m.board.selected.includes(i)}"`)).join('')}</div><div class="b15-meter"><i style="width:${p/10}%"></i></div><small>${p} / 1000 = ${p/1000}</small><div class="b15-meter other"><i style="width:12%"></i></div><small>12 / 100 = 12%</small></div>`;}
function signs(t,m){const b=m.board,rows=signRows(t),next=rows[b.rows.length];return `<div class="b15-signs">${rows.map((r,i)=>`<div><span>${r.a} ${opText(r.op)} ${r.b}</span><b>${b.rows[i]?.value??'?'}</b>${t.mode==='sequence'&&i?'<small>前一行怎样走到这里？</small>':''}</div>`).join('')}</div>${next?`<p>现在接：${next.a} ${opText(next.op)} ${next.b}</p>`:'<p>每一行已经接好。观察大小与方向的变化。</p>'}`;}
function inverse(t,m){return `<div class="b15-forward"><span>${t.start}</span>${t.forward.map(s=>`<span>→ ${s.op==='square'?'平方':s.op==='sqrt'?'开平方':opText(s.op)+' '+s.amount}</span>`).join('')}<b>→ ${t.end}</b></div><div class="b15-backward"><b>${t.end}</b>${m.board.steps.map(s=>`<span>→ ${s.op==='square'?'平方':s.op==='sqrt'?'开平方':opText(s.op)+' '+s.amount}</span><b>→ ${s.value}</b>`).join('')}</div>`;}
function decimalDivide(t,m){const b=m.board,pos=decimalPosition(t,b),prev=b.steps.at(-1)?.r||0;return `<div class="b15-division"><p class="b15-expression">${t.decimal} ÷ ${t.divisor}</p><div class="b15-digit-row">${b.digits.map((d,i)=>`<span class="${i===b.steps.length?'active':''}">${i===t.decimal.split('.')[0].length?'<i>.</i>':''}${b.steps[i]?.q??'·'}</span>`).join('')}</div><div class="b15-digit-row original">${b.digits.map((d,i)=>`<span>${i===t.decimal.split('.')[0].length?'<i>.</i>':''}${d}</span>`).join('')}</div><div class="b15-record">${b.steps.map((s,i)=>`<span>${s.current} 个${unit(t.decimal.split('.')[0].length-1-i)}：分${s.q}，拿走${s.used}，余${s.r}</span>`).join('')}</div></div>${!divisionFinished(t,b)&&b.steps.length<b.digits.length?`<div class="b15-exchange">${b.ready?`<strong>${b.current} 个${unit(pos)}，平均分 ${t.divisor} 份</strong>`:`<span>剩 ${prev} 个${unit(pos+1)} → 换成多少个${unit(pos)}？</span><span>再接上原来的 ${b.digits[b.steps.length]} 个${unit(pos)}</span>`}</div>`:''}`;}
function estimate(t,m){const b=m.board,run=b.runs.at(-1),max=Math.max(1,(b.estimate?.value||0)*1.4,t.candidate||0,run?.value||0),point=(v,label)=>`<span style="left:${Math.max(0,Math.min(98,v/max*95))}%"><i></i>${esc(label)} ${v}</span>`;return `<p class="b15-expression">${t.a} ${opText(t.op)} ${t.b}</p>${b.estimate?`<div class="b15-estimate-axis">${point(b.estimate.value,'估计')}${t.candidate?point(t.candidate,'待检查'):run?.value!=null?point(run.value,'计算'):''}</div><p>留下的估计：${b.estimate.left} ${opText(t.op)} ${b.estimate.right} ≈ ${b.estimate.value}</p>`:'<div class="b15-empty">先留下大概，再打开计算或待检查的结果。</div>'}${t.calculator&&run?`<div class="b15-calculator"><small>${esc(run.entry)}</small><strong>${run.value===null?'检查输入':run.value}</strong></div>`:''}${t.candidate&&b.estimate?`<p>待检查的结果：${t.candidate}</p>`:''}${t.context?`<p>${esc(t.context)}</p>`:''}`;}
function bars(t,m){const c=Math.min(12,Math.max(0,number(m.count)||0)),p=Math.min(36,Math.max(0,number(m.part)||0)),x=Math.min(12,Math.max(0,number(m.extra)||0)),scale=Math.min(9,520/Math.max(t.part*t.factor,40));return `<div class="b15-bars"><span>原来的一份</span><div class="b15-barline"><i style="width:${p*scale}px">${p}</i></div><span>同样的一份，接 ${c} 份</span><div class="b15-barline">${Array.from({length:c},()=>`<i style="width:${p*scale}px">${p}</i>`).join('')}</div><span>原来的一份，只多 ${x}</span><div class="b15-barline"><i style="width:${p*scale}px">${p}</i><i class="extra" style="width:${x*scale}px">${x}</i></div></div>`;}
function pairs(t,m){const b=m.board;return `<div class="b15-pair-picker"><div>${t.rows.map((s,i)=>button('b15-left',esc(s),`data-index="${i}" aria-pressed="${b.left===i}"`)).join('')}</div><b>配</b><div>${t.cols.map((s,i)=>button('b15-pair',esc(s),`data-index="${i}" ${b.left===null?'disabled':''}`)).join('')}</div></div><table class="b15-pair-table"><thead><tr><th>已留下的搭配</th>${t.cols.map(s=>`<th>${esc(s)}</th>`).join('')}</tr></thead><tbody>${t.rows.map((s,i)=>`<tr><th>${esc(s)}</th>${t.cols.map((v,j)=>`<td>${b.pairs.includes(i+','+j)?'●':'·'}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function story(t,m){const b=m.board;return `<div class="b15-card-pool">${b.groups.map((g,i)=>`<section>${button('b15-pick',String(g.value),`data-index="${i}" aria-pressed="${b.selected.includes(i)}" ${b.groups.length===1?'disabled':''}`)}<span>${g.ids.length===1?esc(t.labels[g.ids[0]]):esc(t.meanings.find(x=>x.id===b.steps.findLast(s=>s.expr===g.expr)?.meaning)?.label||'刚合出的量')}</span></section>`).join('')}</div><ol class="b15-record">${b.steps.map(s=>`<li>${s.left} ${opText(s.op)} ${s.right} = ${s.value} · ${esc(t.meanings.find(x=>x.id===s.meaning)?.label||'这一步在找什么？')}</li>`).join('')}</ol>`;}
export function visual(t,m){switch(t.type){case'x-orderlab':return order(t,m);case'x-lawtiles':return laws(t,m);case'x-shapeangle':return shape(t,m);case'x-fractionbridge':return fraction(t,m);case'x-signwalk':return signs(t,m);case'x-undolab':return inverse(t,m);case'x-decimalproduct':return `<p class="b15-expression">${t.decimal} × ${t.multiplier}</p><p>下面每个“一”代表原来的 ${t.decimal.split('.')[1].length===1?'十分之一':'百分之一'}，算完要换回原单位。</p>${v14.visual(innerTask(t),m.inner).replace('两行的单位已经放好','这一行的单位已经放好')}`;case'x-decimaldivide':return decimalDivide(t,m);case'x-estimatepad':return estimate(t,m);case'x-comparebars':return bars(t,m);case'x-pairtable':return pairs(t,m);case'x-storychain':return story(t,m);}return'';}
export function controls(t,m){const b=m.board;switch(t.type){
 case'x-orderlab':return (t.construct?f('expression',t.insert?'只添括号，数字与运算符不变':'把关系写成算式（可用 * / ^）',m.expression)+button('b15-build','按这个关系摆出来'):'')+(t.writeOnly?(t.reason?select('reason','这两个表达式怎样比较',m.reason,t.choices):''):b.tree?(b.selected!==null?f('result','选中这一小块，得到多少',m.result)+button('b15-reduce','合成这一块'):'<p>点一块运算，决定从哪里开始。</p>')+(Object.hasOwn(b.done,b.tree.id)?f('answer','最后得到多少',m.answer):''):'');
 case'x-lawtiles':return button('b15-tile','放一条 n','data-value="n"')+button('b15-tile',`放一块 ${t.b}`,'data-value="c"')+range('n','让 n 变一变',m.n,1,8)+button('b15-trial','比较两边的量')+(b.trials.length>=2?f('coeff','一共有几条 n',m.coeff)+f('constant','固定的小块合起来多少',m.constant):'');
 case'x-shapeangle':return range('skew','斜着或摆正',m.skew,0,60,10)+button('b15-shape','留下这个形状')+(b.seen.includes(0)?f('angleB','摆正后，B角是多少度',m.angleB)+f('angleC','C角是多少度',m.angleC)+f('angleD','D角是多少度',m.angleD)+select('reason','从平行的对边怎样推出',m.reason,[['opposite-adjacent','对角相等，相邻两角合180°'],['all-parallelograms','所有两对边平行的图都只有直角']]):'');
 case'x-fractionbridge':return range('thousandths','下面涂到千分之几，与上面一样长',m.thousandths,0,1000,1)+f('percent','这一份是百分之几',m.percent)+select('answer','八分之一与12%比',m.answer,[['greater','八分之一更多'],['equal','一样多'],['less','八分之一更少']])+select('reason','这样直接比的前提',m.reason,[['same','两条用同样大的整体'],['any','整体大小可以不同']]);
 case'x-signwalk':return b.rows.length<signRows(t).length?f('result','下一行的结果',m.result)+button('b15-sign','把这一行接上'):(t.reason?select('reason','这列每往下一行',m.reason,[['plus3','结果增加3'],['minus3','结果减少3'],['same','结果不变']]):'<p>每一行都留下了。</p>');
 case'x-undolab':return b.steps.length<t.forward.length?select('operator','撤回这一步用什么',m.operator,[...ops,['sqrt','取非负平方根'],['square','平方']])+f('amount','加减乘除用几（平方或开平方可留空）',m.amount)+f('result','撤回后到哪里',m.result)+button('b15-undo-step','撤回这一步'):f('answer','最后回到哪个数',m.answer)+(t.absolute?select('reason','从−3开始，为何现在是3',m.reason,[['nonnegative','平方丢掉正负区别，平方根取非负数'],['negative','平方根总是原来的负数']]):'');
 case'x-decimalproduct':return prefix(v14.controls(innerTask(t),m.inner)).replace('把各行合起来，精确结果是多少','小单位合起来，一共有多少份')+(m.inner.board.rows.length===String(t.multiplier).length?select('unit','多少份当前小单位合成1',m.unit,[['1','1份'],['10','10份'],['100','100份']])+f('answer','换回原单位，原题的积是多少',m.answer):'');
 case'x-decimaldivide':if(b.point===null)return select('point','从左往右，点放在第几位数字之后',m.point,[['1','第1位之后'],['2','第2位之后'],['3','第3位之后']])+button('b15-point','把点对齐');else if(divisionFinished(t,b))return f('answer','每份是多少',m.answer)+f('check','用乘法写出倒查的等式',m.check);else if(b.steps.length===b.digits.length)return button('b15-zero','补一个0，继续分更小的单位');else return b.ready?f('q','这一位每份分到几（0到9）',m.q)+f('used','乘回去一共分走几',m.used)+f('rest','这一段还剩几',m.rest)+button('b15-div-step','记下这一位'):f('exchange','剩余换成更小单位，有多少',m.exchange)+button('b15-bring','换小单位，再带下这一位');
 case'x-estimatepad':return !b.estimate?f('left',`把 ${t.a} 看成附近容易算的数`,m.left)+f('right',`把 ${t.b} 看成附近容易算的数`,m.right)+f('estimate','先算这个大概',m.estimate)+button('b15-estimate','留下估计'):(t.calculator?f('entry','输入计算器算式（可用 * /）',m.entry)+button('b15-calculate','计算'):'')+(!t.calculator||b.runs.length?(t.candidate?select('judgment','待检查结果与估计比较',m.judgment,[['plausible','数量大致合理，仍需核对'],['unreasonable','数量明显不对，要重查']]):'')+select('proof','估计接近，能证明精确答案完全正确吗',m.proof,[['not-proof','不能，还要核对计算与情境'],['proof','能，只要接近就一定对']])+(t.method?select('method','这道题你愿意用什么方法',m.method,[['mental','用数的关系直接算'],['written','写下来逐步算'],['calculator','用计算器并核对输入']]):'')+(t.interpret?select('reason','这个故事要怎样读结果',m.reason,[['up','多准备一个整份，全部安排下'],['down','只数完整装满的份'],['exact','可以继续分，保留精确的小数']]):'')+(t.exact||t.calculator?f('answer','按问题写最终结果',m.answer):''):'');
 case'x-comparebars':return f('count','相同的一份，要接几份',m.count)+f('part','原来的一份长多少',m.part)+f('extra','只多几的那条，额外接多少',m.extra)+button('b15-bars','按这些量搭好')+(b.built?f('answer',t.unknown==='part'?'原来的一份是多少':t.unknown==='factor'?'相当于几份':'几倍的那条是多少',m.answer)+f('addAnswer','只多几的那条，一共多少',m.addAnswer)+f('equation','用n表示故事里的未知量，写关系',m.equation):'');
 case'x-pairtable':return f('answer','一共找到多少种不同搭配',m.answer)+f('equation','用n表示搭配总数，写关系',m.equation);
 case'x-storychain':return b.groups.length>1?select('operator','按点选先后，怎样算两张',m.operator,ops)+f('result','这一步得到多少',m.result)+select('meaning','这一步在找什么',m.meaning,t.meanings.map(x=>[x.id,x.label]))+button('b15-merge','用这两张接出下一步',b.selected.length!==2?'disabled':'')+(b.steps.length?button('b15-back','退一步换个办法'):''):f('answer','最后结果是多少',m.answer)+(t.equations?f('equation','用n表示所求，写完整关系',m.equation):'')+button('b15-back','退一步换个办法');
}return'';}
export const render=(t,m)=>`<section class="b15-work ${t.type==='x-decimalproduct'?'b14-work':''}"><div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}${m.issue?`<p class="b15-issue" role="status">${esc(m.issue)}</p>`:''}${button('b15-reset','重新做，保留之前的尝试')}</div></section>`;
